import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.jwovEGr5.js";const g=JSON.parse('{"title":"Theory Map: CS Concepts in Frensense","description":"","frontmatter":{},"headers":[],"relativePath":"frensense-paper/10_THEORY_MAP.md","filePath":"frensense-paper/10_THEORY_MAP.md"}'),s={name:"frensense-paper/10_THEORY_MAP.md"};function o(r,e,c,l,d,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="theory-map-cs-concepts-in-frensense" tabindex="-1">Theory Map: CS Concepts in Frensense <a class="header-anchor" href="#theory-map-cs-concepts-in-frensense" aria-label="Permalink to &quot;Theory Map: CS Concepts in Frensense&quot;">​</a></h1><p>Every significant algorithmic decision in Frensense maps to an established computer science concept. This document lists them, where they appear in the code, and how they are applied.</p><hr><h2 id="_1-locality-sensitive-hashing-minhash-banded-lsh" tabindex="-1">1. Locality-Sensitive Hashing (MinHash + Banded LSH) <a class="header-anchor" href="#_1-locality-sensitive-hashing-minhash-banded-lsh" aria-label="Permalink to &quot;1. Locality-Sensitive Hashing (MinHash + Banded LSH)&quot;">​</a></h2><p><strong>CS Field:</strong> Approximate algorithms, similarity search, randomized algorithms</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/minhash.rs</code> - MinHash computation, LSH banding, <code>LSHIndex</code></li><li><code>frensense-engine/src/corpus/registry.rs</code> - LSH index construction and candidate retrieval</li></ul><p><strong>Theory:</strong></p><p>MinHash approximates the Jaccard coefficient without computing the exact set intersection:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>J(A, B) = |A ∩ B| / |A ∪ B|</span></span></code></pre></div><p>For a random permutation <code>π</code> of the universe: <code>P[min(π(A)) = min(π(B))] = J(A, B)</code>.</p><p>Banded LSH amplifies the signal: with <code>b</code> bands of <code>r</code> rows each:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P[collision in ≥ 1 band] = 1 - (1 - J^r)^b</span></span></code></pre></div><p>This creates an S-curve in collision probability vs. Jaccard - near-zero below the threshold, near-one above it.</p><p><strong>Current parameters:</strong></p><ul><li>120 hash functions (120-dimensional signature)</li><li>40 bands, 12 rows per band</li><li>Threshold ≈ 0.71 at 50% recall</li></ul><p><strong>Why this matters:</strong> Without LSH, corpus matching would be O(N × P) where N = functions and P = patterns. LSH reduces this to O(N × candidates) where <code>candidates ≪ P</code> - enabling sub-second scans on large codebases.</p><p><strong>Key papers:</strong> Broder 1997, Indyk &amp; Motwani 1998.</p><hr><h2 id="_2-taint-analysis-information-flow-analysis" tabindex="-1">2. Taint Analysis (Information Flow Analysis) <a class="header-anchor" href="#_2-taint-analysis-information-flow-analysis" aria-label="Permalink to &quot;2. Taint Analysis (Information Flow Analysis)&quot;">​</a></h2><p><strong>CS Field:</strong> Program analysis, security, information flow control</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/data_flow/</code> - 13 modules covering the full taint pipeline</li><li><code>src/semantics/simple_taint.rs</code> - intraprocedural taint rule</li><li><code>src/semantics/data_flow/</code> - interprocedural taint rule</li></ul><p><strong>Theory:</strong></p><p>Taint analysis is an <strong>information flow</strong> technique: it tracks <em>labels</em> (taint marks) propagated through program operations according to a <em>taint policy</em>. The fundamental question: &quot;Can data from source <code>s</code> reach sink <code>k</code> without passing through a sanitizer?&quot;</p><p><strong>Frensense uses May-Taint (sound, not complete):</strong> If there exists <em>any path</em> in the CFG along which tainted data could reach the sink, the function is flagged. This errs on the side of more warnings (false positives are possible, false negatives are not).</p><p><strong>Scope stack lattice:</strong> <code>TaintRegistry</code> implements a scope stack where the join of tainted and untainted is tainted. This is the standard over-approximation for conditional sanitization:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (safe) {</span></span>
<span class="line"><span>    x = sanitize(y);  // y is untainted in this branch</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    x = y;            // y is still tainted here</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// At join point: x is TAINTED (conservative)</span></span></code></pre></div><p><strong>Key papers:</strong> Newsome &amp; Song 2005, Livshits &amp; Lam 2005.</p><hr><h2 id="_3-control-flow-graphs-and-dominance-analysis" tabindex="-1">3. Control Flow Graphs and Dominance Analysis <a class="header-anchor" href="#_3-control-flow-graphs-and-dominance-analysis" aria-label="Permalink to &quot;3. Control Flow Graphs and Dominance Analysis&quot;">​</a></h2><p><strong>CS Field:</strong> Compiler construction, program analysis</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/cfg/mod.rs</code> - <code>ControlFlowGraph</code>, <code>BasicBlock</code>, <code>CFEdgeKind</code></li><li><code>frensense-engine/src/cfg/def_use.rs</code> - reaching definitions, def-use chains</li></ul><p><strong>Theory:</strong></p><p>A <strong>Control Flow Graph (CFG)</strong> <code>G = (V, E)</code> has a vertex per basic block and edges per control transfer. Basic blocks are maximal straight-line sequences with a single entry and single exit.</p><p><strong>Dominance:</strong> Node <code>d</code> <em>dominates</em> node <code>n</code> if every path from the program entry to <code>n</code> passes through <code>d</code>. Frensense uses dominance to verify that auth checks <em>must</em> execute before sensitive operations - if the auth check doesn&#39;t dominate the sensitive op, there&#39;s a bypass path.</p><p><strong>Reaching Definitions:</strong> A definition <code>d: x = e</code> at node <code>n</code> <em>reaches</em> node <code>m</code> if there is a CFG path from <code>n</code> to <code>m</code> along which <code>x</code> is not redefined. Implemented as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IN[B]  = ∪ OUT[pred(B)]</span></span>
<span class="line"><span>OUT[B] = gen[B] ∪ (IN[B] - kill[B])</span></span></code></pre></div><p><strong>Key papers:</strong> Cooper et al. 2001 (&quot;A Simple, Fast Dominance Algorithm&quot;), Allen 1970.</p><hr><h2 id="_4-tree-edit-distance" tabindex="-1">4. Tree Edit Distance <a class="header-anchor" href="#_4-tree-edit-distance" aria-label="Permalink to &quot;4. Tree Edit Distance&quot;">​</a></h2><p><strong>CS Field:</strong> String/tree algorithms, bioinformatics, AST analysis</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/ast_distance.rs</code> - skeleton extraction and TED computation</li></ul><p><strong>Theory:</strong></p><p><strong>Tree Edit Distance (TED)</strong> measures the minimum number of node insertions, deletions, and relabelings to transform one labeled ordered tree into another.</p><p>Frensense uses a simplified variant:</p><ol><li>Extract the structural <em>skeleton</em> of each function: ordered sequence of normalized node kinds, stripping identifiers and literals.</li><li>Node normalization: all loops → <code>loop_node</code>, all branches → <code>branch_node</code>, all try blocks → <code>try_node</code>. This collapses syntactic variation across languages.</li><li>Compute TED on the normalized skeletons.</li></ol><p>The normalization step is essential: without it, <code>while</code> and <code>for</code> loops would have TED = 1 (one relabeling), when they are semantically equivalent and should have TED = 0.</p><p><strong>CS Theory:</strong> Zhang-Shasha algorithm (1989), O(n²m²) worst case.</p><hr><h2 id="_5-tf-idf-weighting" tabindex="-1">5. TF-IDF Weighting <a class="header-anchor" href="#_5-tf-idf-weighting" aria-label="Permalink to &quot;5. TF-IDF Weighting&quot;">​</a></h2><p><strong>CS Field:</strong> Information retrieval, text mining</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/fingerprint/types.rs</code> - <code>compute_idf_weights()</code>, <code>apply_idf_weights()</code></li><li><code>frensense-engine/src/corpus/registry.rs</code> - <code>idf_weights</code>, <code>api_idf_weights</code></li></ul><p><strong>Theory:</strong></p><p><strong>TF-IDF (Term Frequency–Inverse Document Frequency)</strong> weights tokens by their discriminative power:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IDF(token) = log(N / df(token))</span></span></code></pre></div><p>where N = total documents (functions) and df(token) = number of documents containing the token.</p><p>In Frensense, each function is a &quot;document&quot; and each n-gram hash is a &quot;term.&quot; Common boilerplate tokens (e.g., <code>import express from &quot;express&quot;</code>) appear in many functions → low IDF → low weight. Rare security-sensitive tokens (e.g., <code>execSync</code>, <code>db.query.raw</code>) appear in few functions → high IDF → high weight.</p><p>The weighted Jaccard similarity uses IDF-weighted overlap rather than raw set size, making rare shared tokens count more than common ones.</p><p><strong>Key paper:</strong> Sparck Jones 1972.</p><hr><h2 id="_6-multi-dimensional-weighted-similarity-scoring" tabindex="-1">6. Multi-Dimensional Weighted Similarity Scoring <a class="header-anchor" href="#_6-multi-dimensional-weighted-similarity-scoring" aria-label="Permalink to &quot;6. Multi-Dimensional Weighted Similarity Scoring&quot;">​</a></h2><p><strong>CS Field:</strong> Information retrieval, metric learning, pattern recognition</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/pattern/similarity.rs</code> - <code>RawDimensions</code>, <code>weighted_score()</code></li><li><code>frensense-engine/src/pattern/scorer.rs</code> - <code>PatternScorer</code>, <code>ScorerConfig</code></li></ul><p><strong>Theory:</strong></p><p>The final score is a <strong>linear combination</strong> of similarity scores across 15 independent dimensions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vuln_score = Σ_{i=0}^{14} w_i · sim_i</span></span></code></pre></div><p>The weights <code>w</code> are learned per vulnerability category. The <strong>identity gate</strong> is a multiplicative pre-condition that prevents matches on code that shares n-grams but lacks any identity-bearing signal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gate = min(max(api_sim, semantic_sim, ast_sim, motif_sim, flow_sim) × 2.5 + 0.1, 1.0)</span></span>
<span class="line"><span>final = vuln_score × gate</span></span></code></pre></div><p>This is related to <strong>weighted Jaccard similarity</strong> and <strong>multivariate scoring</strong> in retrieval systems.</p><p><strong>Issue visible in code:</strong> The gate formula <code>identity_gate * 2.5 + 0.1</code> adds a floor of 0.1, meaning a function with <em>zero</em> identity signal still passes 10% of the gate. This is a known FP contributor - see <a href="./12_LIMITATIONS.html"><code>12_LIMITATIONS.md</code></a>.</p><hr><h2 id="_7-contrastive-learning-discriminative-pattern-matching" tabindex="-1">7. Contrastive Learning (Discriminative Pattern Matching) <a class="header-anchor" href="#_7-contrastive-learning-discriminative-pattern-matching" aria-label="Permalink to &quot;7. Contrastive Learning (Discriminative Pattern Matching)&quot;">​</a></h2><p><strong>CS Field:</strong> Metric learning, discriminative training</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/pattern/scorer.rs</code> - contrastive scoring</li><li><code>frensense-bundler/src/pattern/weight_learner.rs</code> - weight optimization</li><li><code>frensense-bundler/src/auto_filter.rs</code> - discriminative feature selection</li></ul><p><strong>Theory:</strong></p><p>Standard similarity matching asks: &quot;How similar is the target to the known pattern?&quot;<br> Contrastive matching asks: &quot;Is the target <em>more similar to the vulnerable version</em> than to the safe version?&quot;</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>contrastive_score = pos_score - neg_penalty_weight × neg_score</span></span></code></pre></div><p>This is analogous to:</p><ul><li><strong>Triplet loss</strong> in metric learning: anchor (pattern), positive (vulnerable), negative (safe).</li><li><strong>Discriminative training</strong> in HMMs: maximize <code>P(vulnerable | features) - P(safe | features)</code>.</li><li><strong>Contrastive loss</strong> (Chopra et al. 2005): minimize distance for same-class pairs, maximize for different-class.</li></ul><p>The key insight: the negative example provides the <em>boundary</em> - the structurally identical but safe version that defines what &quot;safe&quot; looks like for this pattern. Without the negative, false positives arise from functions that are structurally similar to the positive but are actually safe.</p><p><strong>Key papers:</strong> Chopra et al. 2005, Schroff et al. 2015 (FaceNet).</p><hr><h2 id="_8-multi-layer-confidence-composition-and-gate-verification" tabindex="-1">8. Multi-Layer Confidence Composition (AND-Gate Verification) <a class="header-anchor" href="#_8-multi-layer-confidence-composition-and-gate-verification" aria-label="Permalink to &quot;8. Multi-Layer Confidence Composition (AND-Gate Verification)&quot;">​</a></h2><p><strong>CS Field:</strong> Fault-tolerant systems, evidence combination, multi-sensor fusion</p><p><strong>Where in code:</strong></p><ul><li><code>src/engine/composition.rs</code> - <code>compose_confidence()</code>, <code>LayerSignals</code></li></ul><p><strong>Theory:</strong></p><p>The composition model is a <strong>4-layer AND-gate</strong>: a finding is only trusted when multiple independent evidence sources agree.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Layer 1 (L1): Corpus match  - structural similarity</span></span>
<span class="line"><span>Layer 2 (L2): Taint flow    - data flow confirmation</span></span>
<span class="line"><span>Layer 3 (L3): Validator     - suppressor (negative evidence)</span></span>
<span class="line"><span>Layer 4 (L4): Near-dup      - amplifier (consistency evidence)</span></span></code></pre></div><p>This is related to:</p><ul><li><strong>Bayesian evidence combination:</strong> each layer updates a prior probability.</li><li><strong>Dempster-Shafer theory:</strong> combining evidence from independent sources.</li><li><strong>Multi-sensor fusion:</strong> in avionics/robotics, critical decisions require agreement from independent sensors.</li></ul><p>The deterministic rule implementation (rather than probabilistic Bayesian updating) is intentional for auditability - every score adjustment has a named, documented cause.</p><hr><h2 id="_9-call-graph-construction-interprocedural-analysis" tabindex="-1">9. Call Graph Construction (Interprocedural Analysis) <a class="header-anchor" href="#_9-call-graph-construction-interprocedural-analysis" aria-label="Permalink to &quot;9. Call Graph Construction (Interprocedural Analysis)&quot;">​</a></h2><p><strong>CS Field:</strong> Compiler theory, program analysis</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/graph.rs</code> - <code>SemanticGraph</code> (petgraph DiGraph)</li><li><code>frensense-engine/src/data_flow/cross_file.rs</code> - interprocedural taint resolver</li></ul><p><strong>Theory:</strong></p><p>A <strong>call graph</strong> <code>CG = (F, E)</code> where F = functions, E = call relations. For a language without dynamic dispatch, an exact call graph can be built statically. For JavaScript/TypeScript, call graph construction is inherently imprecise due to:</p><ul><li>First-class functions</li><li>Dynamic <code>require()</code></li><li>Prototype inheritance</li><li>Event-driven dispatch</li></ul><p>Frensense uses a <strong>name-based approximation</strong>: call edges are established by matching call site names to function definitions by name within the project. This is roughly at the precision level of <strong>CHA (Class Hierarchy Analysis)</strong> - fast but may create phantom edges.</p><p>The call graph is used for:</p><ul><li>Cross-file taint propagation (BFS over <code>Calls</code> edges)</li><li>Function reachability queries</li><li>Temporal property checking (are operations <code>A</code> and <code>B</code> reachable in the same call chain?)</li></ul><p><strong>Key papers:</strong> Ryder 1979, Grove et al. 1997.</p><hr><h2 id="_10-linear-temporal-logic-ltl-property-checking" tabindex="-1">10. Linear Temporal Logic (LTL) Property Checking <a class="header-anchor" href="#_10-linear-temporal-logic-ltl-property-checking" aria-label="Permalink to &quot;10. Linear Temporal Logic (LTL) Property Checking&quot;">​</a></h2><p><strong>CS Field:</strong> Formal verification, model checking</p><p><strong>Where in code:</strong></p><ul><li><code>src/temporal/analyzer.rs</code> - sequence property checker</li><li><code>src/temporal/config.rs</code> - built-in temporal rules</li></ul><p><strong>Theory:</strong></p><p><strong>Linear Temporal Logic (LTL)</strong> extends propositional logic with temporal operators:</p><ul><li><code>G φ</code> - φ holds globally (on all future states)</li><li><code>F φ</code> - φ holds eventually (on some future state)</li><li><code>X φ</code> - φ holds in the next state</li><li><code>φ U ψ</code> - φ holds until ψ holds</li></ul><p>Frensense checks properties of the form: <code>G(A → F(B))</code> - &quot;globally, whenever A occurs, B eventually follows.&quot; For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>G(fundWallet → F(createLedgerEntry))</span></span></code></pre></div><p>&quot;Whenever <code>fundWallet</code> is called, <code>createLedgerEntry</code> must eventually be called (in the same function).&quot;</p><p>The implementation is <strong>bounded model checking</strong> restricted to a single function&#39;s execution trace, not full LTL model checking. This makes it tractable but misses inter-function sequencing properties.</p><p><strong>Key papers:</strong> Pnueli 1977, Clarke &amp; Emerson 1981.</p><hr><h2 id="_11-semantic-motifs-and-api-abstraction" tabindex="-1">11. Semantic Motifs and API Abstraction <a class="header-anchor" href="#_11-semantic-motifs-and-api-abstraction" aria-label="Permalink to &quot;11. Semantic Motifs and API Abstraction&quot;">​</a></h2><p><strong>CS Field:</strong> Abstract interpretation, program analysis vocabulary</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/corpus/motifs.rs</code> - <code>MOTIFS</code> static table, <code>MOTIF_LOOKUP</code></li><li><code>frensense-engine/src/corpus/flow_fingerprint.rs</code> - motif-based source/sink detection</li></ul><p><strong>Theory:</strong></p><p>A <strong>motif</strong> is an equivalence class of API calls under semantic equivalence. Formally:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>motif(call) = canonical_name if call ∈ motif_members</span></span></code></pre></div><p>At fingerprint time:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hash(&quot;exec&quot;)     → hash(&quot;CommandExecutionSink&quot;)</span></span>
<span class="line"><span>hash(&quot;spawn&quot;)    → hash(&quot;CommandExecutionSink&quot;)</span></span>
<span class="line"><span>hash(&quot;Command::new&quot;) → hash(&quot;CommandExecutionSink&quot;)</span></span></code></pre></div><p>This is analogous to:</p><ul><li><strong>Abstract interpretation:</strong> replacing concrete values with abstract representatives.</li><li><strong>Concept lattices:</strong> grouping calls by their semantic category.</li><li><strong>Defunctionalization:</strong> replacing first-class function calls with tagged variants.</li></ul><p>The key benefit: a pattern trained on one API (<code>exec</code>) automatically generalizes to semantically equivalent APIs (<code>spawn</code>, <code>system</code>, <code>execFile</code>) without any additional corpus examples. This is cross-framework and cross-language generalization at the semantic level.</p><hr><h2 id="_12-probability-calibration-platt-scaling" tabindex="-1">12. Probability Calibration (Platt Scaling) <a class="header-anchor" href="#_12-probability-calibration-platt-scaling" aria-label="Permalink to &quot;12. Probability Calibration (Platt Scaling)&quot;">​</a></h2><p><strong>CS Field:</strong> Machine learning, statistics</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-bundler/src/calibration.rs</code> - sigmoid fitting</li><li><code>frensense-engine/src/corpus/registry.rs</code> - calibration application</li></ul><p><strong>Theory:</strong></p><p>Raw similarity scores <code>s ∈ [0, 1]</code> are not calibrated probabilities. A score of 0.7 does not mean 70% probability. <strong>Platt scaling</strong> (also called logistic calibration) fits:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(match | s) = σ(A·s + B) = 1 / (1 + e^{-(A·s + B)})</span></span></code></pre></div><p>Parameters <code>(A, B)</code> are fit by maximum likelihood on a held-out validation set of (score, label) pairs. The fitted sigmoid maps raw scores to calibrated confidence values that are statistically meaningful.</p><p>Per-pattern calibration accounts for the fact that different patterns have different difficulty: a SQL injection pattern may need a raw score of 0.75 to achieve 0.65 confidence, while a hardcoded-secret pattern may achieve the same confidence at a raw score of 0.50.</p><p><strong>Key paper:</strong> Platt 1999.</p><hr><h2 id="_13-shingling-and-document-similarity" tabindex="-1">13. Shingling and Document Similarity <a class="header-anchor" href="#_13-shingling-and-document-similarity" aria-label="Permalink to &quot;13. Shingling and Document Similarity&quot;">​</a></h2><p><strong>CS Field:</strong> Information retrieval, near-duplicate detection</p><p><strong>Where in code:</strong></p><ul><li><code>frensense-engine/src/fingerprint/hashing.rs</code> - <code>token_ngrams_sorted()</code>, <code>token_ngrams_positional()</code></li></ul><p><strong>Theory:</strong></p><p><strong>Shingling</strong> (w-shingling): represent a document as the set of all its overlapping w-token windows. For a token sequence <code>[t1, t2, t3, t4, t5]</code> with w=3:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shingles = {(t1,t2,t3), (t2,t3,t4), (t3,t4,t5)}</span></span></code></pre></div><p>Frensense hashes each shingle to a <code>u64</code> and stores the set as <code>ngram_hashes</code>. Jaccard similarity between two shingle sets approximates the probability that a random position in both documents contains the same w-gram - a measure of content overlap.</p><p>Positional n-grams (used for <code>cf_order_sim</code>) include the position index: <code>hash(position, t_i, t_{i+1}, t_{i+2})</code>. These are not Jaccard-compatible but capture sequence order for cosine similarity computation.</p><hr><h2 id="summary-table" tabindex="-1">Summary Table <a class="header-anchor" href="#summary-table" aria-label="Permalink to &quot;Summary Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CS Concept</th><th>Frensense Module</th><th>Purpose</th></tr></thead><tbody><tr><td>MinHash LSH</td><td><code>minhash.rs</code>, <code>registry.rs</code></td><td>Sub-linear corpus retrieval</td></tr><tr><td>May-taint analysis</td><td><code>data_flow/</code></td><td>Source→sink flow detection</td></tr><tr><td>Scope-stack lattice</td><td><code>data_flow/mod.rs::TaintRegistry</code></td><td>Conservative taint propagation</td></tr><tr><td>Control flow graph</td><td><code>cfg/mod.rs</code></td><td>Path-sensitive analysis, dominator computation</td></tr><tr><td>Reaching definitions</td><td><code>cfg/def_use.rs</code></td><td>Def-use chains for taint</td></tr><tr><td>Tree edit distance</td><td><code>ast_distance.rs</code></td><td>Structural similarity (ast_sim dimension)</td></tr><tr><td>TF-IDF weighting</td><td><code>fingerprint/types.rs</code></td><td>Down-weight boilerplate tokens</td></tr><tr><td>Weighted linear scoring</td><td><code>pattern/similarity.rs</code></td><td>Multi-dimensional match confidence</td></tr><tr><td>Identity gate</td><td><code>pattern/similarity.rs</code></td><td>Prevent boilerplate false positives</td></tr><tr><td>Contrastive learning</td><td><code>pattern/scorer.rs</code></td><td>Positive vs. negative discrimination</td></tr><tr><td>Discriminative feature selection</td><td><code>frensense-bundler/auto_filter.rs</code></td><td>Auto-derive SemanticFilters</td></tr><tr><td>AND-gate evidence combination</td><td><code>engine/composition.rs</code></td><td>Multi-layer confirmation</td></tr><tr><td>Name-based call graph</td><td><code>graph.rs</code>, <code>data_flow/cross_file.rs</code></td><td>Interprocedural taint propagation</td></tr><tr><td>LTL sequence checking</td><td><code>temporal/analyzer.rs</code></td><td>Financial and auth invariants</td></tr><tr><td>API abstraction (motifs)</td><td><code>corpus/motifs.rs</code></td><td>Cross-framework generalization</td></tr><tr><td>Sigmoid calibration</td><td><code>frensense-bundler/calibration.rs</code></td><td>Convert scores to probabilities</td></tr><tr><td>W-shingling</td><td><code>fingerprint/hashing.rs</code></td><td>N-gram set representation</td></tr><tr><td>LRU cache</td><td><code>src/lib.rs::TaintCache</code></td><td>Taint walk memoization</td></tr><tr><td>Visitor pattern</td><td><code>FrensenseRule::check</code></td><td>AST rule dispatch</td></tr><tr><td>Strategy pattern</td><td><code>LanguageSpec</code> trait</td><td>Language polymorphism</td></tr></tbody></table>`,160)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
